    /\bI\s+am\s+(?:unable|not\s+allowed)\s+to\s+.*\b(?:policy|safety)/i,
    /\bviolation\s+of\s+(?:safety|policy)\s+protocols/i,
    /\bdue\s+to\s+(?:safety\s+)?policy\s+\w{1,5}-?\d+/i,
    /\b(?:safety|security)\s+(?:policy|constraint)\s+\w{1,5}-?\d+\b/i,
  ];

