    else if (Array.isArray(content)) {
      for (const block of content) {
        if (block.type === "text" && block.text) texts.push(block.text);
      }
    }

    for (const text of texts) {
      for (const pattern of policyPatterns) {
        const match = text.match(pattern);
        if (match) {
